import{_ as e,c as t,o,a4 as n}from"./chunks/framework.ttppV29E.js";const r="/assets/jwt-bearer-create.bF9-4Fqn.png",i="/assets/jwt-bearer-use.DQf7COz_.png",m=JSON.parse('{"title":"JWT Bearer","description":"","frontmatter":{},"headers":[],"relativePath":"docs/connections/jwt-bearer.md","filePath":"docs/connections/jwt-bearer.md","lastUpdated":1786714481000}'),a={name:"docs/connections/jwt-bearer.md"},s=n('<h1 id="jwt-bearer" tabindex="-1">JWT Bearer <a class="header-anchor" href="#jwt-bearer" aria-label="Permalink to &quot;JWT Bearer&quot;">​</a></h1><p>The JWT Bearer connection stores the details required to obtain an access token from an OAuth2 authorisation server using the JWT Bearer grant (<a href="https://datatracker.ietf.org/doc/html/rfc7523" target="_blank" rel="noreferrer">RFC 7523</a>), where a signed JSON Web Token is presented directly as proof of identity instead of a shared client secret. This is commonly used for server-to-server authentication scenarios where a static secret is undesirable, such as authenticating with Google service accounts.</p><h2 id="creating-a-jwt-bearer-connection" tabindex="-1">Creating a JWT Bearer Connection <a class="header-anchor" href="#creating-a-jwt-bearer-connection" aria-label="Permalink to &quot;Creating a JWT Bearer Connection&quot;">​</a></h2><p>To add a new JWT Bearer Connection:</p><ol><li>Go to the <strong>Connections</strong> section in AireGlu.</li><li>Click the <strong>Add</strong> button.</li><li>Select <strong>JWT Bearer</strong> as the connection you want to create</li><li>Fill in the required fields: <ul><li><strong>Key</strong>: A unique identifier for this connection (e.g., <code>my-jwt-bearer</code>).</li><li><strong>Display Name</strong>: A friendly name for easy reference.</li><li><strong>Token Endpoint</strong>: The token endpoint URL provided by your authorisation server.</li><li><strong>Issuer</strong>: The <code>iss</code> claim for the signed assertion - typically the client or service account identifier recognised by your authorisation server.</li><li><strong>Audience</strong>: The <code>aud</code> claim for the signed assertion. This must match what your authorisation server expects. For many providers, including Google, this is the same value as the Token Endpoint.</li></ul></li><li>Under <strong>Key Configuration</strong>, provide the details of the key used to sign the JWT assertion: <ul><li><strong>Private Key</strong>: Reference an AireGlu secret that contains the private key.</li><li><strong>Key Format</strong>: Choose <strong>JWK</strong> or <strong>PEM</strong> depending on the format of your private key.</li><li><strong>Key ID</strong>: The key identifier (<code>kid</code>) associated with the private key.</li><li><strong>Signing Algorithm</strong>: The algorithm used to sign the assertion (e.g., <code>RS256</code>).</li><li><strong>Assertion Lifetime</strong>: How long, in seconds, the signed assertion is valid for, up to a maximum of 3600 seconds (60 minutes).</li></ul></li><li>(Optional) Add any <strong>Claims</strong> required by your authorisation server (e.g., <code>scope</code>). Note that <code>iss</code>, <code>aud</code>, <code>iat</code>, <code>exp</code>, <code>nbf</code> and <code>jti</code> are reserved and cannot be set here, as AireGlu manages these automatically.</li><li>(Optional) Add any additional <strong>Parameters</strong> required by your authorisation server&#39;s token request. Note that <code>grant_type</code>, <code>assertion</code> are reserved and cannot be set here.</li><li>Click <strong>Save connection</strong>.</li></ol><p><img src="'+r+'" alt="Create JWT Bearer Connection"></p><h2 id="using-a-jwt-bearer-connection-in-http-request-tasks" tabindex="-1">Using a JWT Bearer Connection in HTTP Request Tasks <a class="header-anchor" href="#using-a-jwt-bearer-connection-in-http-request-tasks" aria-label="Permalink to &quot;Using a JWT Bearer Connection in HTTP Request Tasks&quot;">​</a></h2><p>Once you have created a JWT Bearer Connection, you can use it to authenticate HTTP requests in your endpoint tasks:</p><ol><li>In your endpoint, add or edit an <strong>HTTP Request Task</strong>.</li><li>Go to the <strong>Authorisation</strong> tab.</li><li>Set <strong>Auth Type</strong> to <strong>Client Connection</strong>.</li><li>Search and select the desired <strong>JWT Bearer Connection</strong>.</li><li>(Optional) Override any parameters for this specific request.</li></ol><p>When the task runs, AireGlu will automatically:</p><ul><li>Build and sign a JWT assertion using the connection&#39;s configured Issuer, Audience, Claims and private key.</li><li>Exchange the signed assertion for an access token using the <code>urn:ietf:params:oauth:grant-type:jwt-bearer</code> grant.</li><li>Inject the resulting bearer token into the HTTP request&#39;s <code>Authorization</code> header.</li><li>Handle token caching and retries as needed, so you don&#39;t have to worry about token management in your endpoint.</li><li>In the event of an authentication failure, the task will log the error details in the metrics under the &quot;Usage Data&quot; tab, allowing you to troubleshoot issues with token retrieval or authentication.</li></ul><p>This makes it easy to securely call external APIs that require the JWT Bearer grant, such as Google service accounts, without manually handling assertion signing in your workflow.</p><p><img src="'+i+'" alt="Use JWT Bearer Connection in HTTP Request Task"></p>',13),c=[s];function l(d,h,u,g,p,T){return o(),t("div",null,c)}const f=e(a,[["render",l]]);export{m as __pageData,f as default};
